import React, { createContext, useState, useContext, useCallback } from "react";

const QueueContext = createContext();

export const QueueProvider = ({ children }) => {
  const [queue, setQueue] = useState([]);
  const [servedTimes, setServedTimes] = useState([]);
  const [currentNumber, setCurrentNumber] = useState(1);
  const [counters, setCounters] = useState(Array(8).fill(null).map(() => []));

  const generateQueueId = (num) => {
    const letterIndex = Math.floor((num - 1) / 999);
    const letter = String.fromCharCode(65 + letterIndex);
    const number = ((num - 1) % 999) + 1;
    return `${letter}${String(number).padStart(3, "0")}`;
  };

  const addQueue = () => {
    if (currentNumber > 25974) return;

    // Use a single functional update to prevent double-firing skips
    setQueue((prevQueue) => {
      // Calculate next ID based on the CURRENT number of items generated so far
      // This is more reliable than relying on the currentNumber state which might be stale
      const nextId = generateQueueId(currentNumber);

      // Check if ID already exists at the end of the line (Strict Mode check)
      if (prevQueue.length > 0 && prevQueue[prevQueue.length - 1].id === nextId) {
        return prevQueue;
      }

      const newItem = { id: nextId, timeCreated: Date.now() };
      
      // Update the global counter only when a successful add happens
      setCurrentNumber(prev => prev + 1);
      return [...prevQueue, newItem];
    });
  };

  const nextQueue = (counterIndex = 0) => {
    setQueue((prevQueue) => {
      if (prevQueue.length === 0) return prevQueue;

      const nextItem = prevQueue[0];
      const remainingQueue = prevQueue.slice(1);

      setServedTimes((prev) => [...prev, Date.now() - nextItem.timeCreated]);

      setCounters((prevCounters) => {
        const newCounters = [...prevCounters];
        // FIX: We replace the whole counter with just the new ID
        // This ensures the "Your Queue" box shows only the current student
        newCounters[counterIndex] = [nextItem.id]; 
        return newCounters;
      });

      return remainingQueue;
    });
  };

  const addToCounter = (counterIndex = 0) => {
    setQueue((prevQueue) => {
      if (prevQueue.length === 0) return prevQueue;
      
      // Prevent counter overload
      if (counters[counterIndex].length >= 5) {
        alert("Counter Full!");
        return prevQueue;
      }

      const nextItem = prevQueue[0];
      const remainingQueue = prevQueue.slice(1);

      setServedTimes((prev) => [...prev, Date.now() - nextItem.timeCreated]);
      setCounters((prevCounters) => {
        const newCounters = [...prevCounters];
        // For AddToCounter, we APPEND (keeping history for that counter)
        newCounters[counterIndex] = [...newCounters[counterIndex], nextItem.id];
        return newCounters;
      });

      return remainingQueue;
    });
  };

  const deleteQueue = () => setQueue((prev) => prev.slice(0, -1));

  const value = {
    counters,
    queueList: queue.map(q => q.id),
    waitingCount: queue.length,
    nextInLine: queue[0]?.id || "---",
    averageWaitTime: servedTimes.length > 0 
      ? Math.round((servedTimes.reduce((a, b) => a + b, 0) / servedTimes.length) / 60000) 
      : 0,
    addQueue,
    nextQueue,
    addToCounter,
    deleteQueue
  };

  return <QueueContext.Provider value={value}>{children}</QueueContext.Provider>;
};

export const useQueue = () => useContext(QueueContext);
